export default async function next(
  { event, baseId, invoiceTable, lineTable, acknowledge, resolution, confirmedInvoiceId },
  ctx,
) {
  if (!baseId || baseId.includes("YOUR_") || !invoiceTable || !lineTable)
    throw Error("Configure Airtable base and tables");
  const e = event;
  if (!e?.data?.job_id || !["parse.success", "parse.error"].includes(e.event_type))
    throw Error("Expected a LlamaParse job event");
  let all = (await ctx.state.get("invoice-parse")) || { jobs: {} };
  let s = all.jobs[e.data.job_id];
  if (!s) {
    s = { phase: e.event_type === "parse.success" ? "read" : "failed", pending: null, index: 0 };
    all.jobs[e.data.job_id] = s;
    await ctx.state.set("invoice-parse", all);
  }
  if (s.pending) {
    if (acknowledge !== s.pending || !["absent", "confirmed"].includes(resolution))
      throw Error("Inspect unknown write " + s.pending);
    if (resolution === "confirmed") {
      if (s.phase === "invoice") {
        if (!confirmedInvoiceId) throw Error("Enter the confirmed invoice record ID");
        s.invoiceId = confirmedInvoiceId;
        s.phase = s.lines.length ? "lines" : "done";
      } else if (s.phase === "lines") {
        s.index++;
        s.phase = s.index < s.lines.length ? "lines" : "done";
      } else throw Error("Unexpected pending phase");
    }
    s.pending = null;
    await ctx.state.set("invoice-parse", all);
  }
  let action = s.phase,
    url = "",
    body = {},
    records = [{ fields: {} }],
    table = invoiceTable;
  if (action === "read")
    url =
      "https://api.cloud.llamaindex.ai/api/v2/parse/" +
      encodeURIComponent(e.data.job_id) +
      "?expand=markdown";
  if (action === "extract") {
    url = "https://api.openai.com/v1/chat/completions";
    body = {
      model: "gpt-4o-mini",
      messages: [
        {
          role: "system",
          content:
            "Extract all invoice line items. Return JSON object with items array, each item has description, qty, unit_price, amount. Quantities and prices must be numbers.",
        },
        { role: "user", content: s.markdown },
      ],
      response_format: { type: "json_object" },
    };
  }
  if (action === "invoice") {
    s.pending = "invoice:" + e.data.job_id;
    await ctx.state.set("invoice-parse", all);
  }
  if (action === "lines") {
    table = lineTable;
    const line = s.lines[s.index];
    records = [
      {
        fields: {
          Description: line.description,
          Qty: line.qty,
          "Unit price": line.unit_price,
          Amount: line.amount,
          Invoices: [s.invoiceId],
        },
      },
    ];
    s.pending = "line:" + e.data.job_id + ":" + s.index;
    await ctx.state.set("invoice-parse", all);
  }
  if (action === "failed") throw Error("LlamaParse reported failed job " + e.data.job_id);
  return { action, url, body, records, baseId, table, jobId: e.data.job_id };
}

