async function result({ jobId, kind, statusCode, body, records }, ctx) {
  const all = await ctx.state.get("invoice-parse"),
    s = all?.jobs?.[jobId];
  if (!s) throw Error("Missing job state");
  if (kind === "read") {
    if (
      statusCode !== 200 ||
      body?.job?.status !== "COMPLETED" ||
      !Array.isArray(body?.markdown?.pages) ||
      body.markdown.pages.some((p) => !p.success)
    )
      throw Error("Parse result incomplete or failed");
    s.markdown = body.markdown.pages.map((p) => p.markdown).join("\n\n");
    s.phase = "extract";
  }
  if (kind === "extract") {
    if (statusCode !== 200) throw Error("OpenAI extraction failed");
    const parsed = JSON.parse(body.choices?.[0]?.message?.content || "null");
    if (!Array.isArray(parsed?.items)) throw Error("Missing extracted items");
    s.lines = parsed.items.map((x) => {
      const r = {
        description: String(x.description || ""),
        qty: Number(x.qty),
        unit_price: Number(x.unit_price),
        amount: Number(x.amount),
      };
      if (!r.description || ![r.qty, r.unit_price, r.amount].every(Number.isFinite))
        throw Error("Invalid line item");
      return r;
    });
    delete s.markdown;
    s.phase = "invoice";
  }
  if (kind === "invoice") {
    if (!records?.[0]?.id) throw Error("Invoice creation result unknown");
    s.invoiceId = records[0].id;
    s.pending = null;
    s.phase = s.lines.length ? "lines" : "done";
  }
  if (kind === "lines") {
    if (!records?.[0]?.id) throw Error("Line creation result unknown");
    s.pending = null;
    s.index++;
    s.phase = s.index < s.lines.length ? "lines" : "done";
  }
  await ctx.state.set("invoice-parse", all);
  return { ok: true };
}

export default async function run({ jobId, statusCode, body, records }, ctx) {
  return result({ jobId, kind: "read", statusCode, body, records }, ctx);
}

